using System.Security.Claims;using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using Microsoft.AspNetCore.Mvc.Rendering;using TechnifyERP.Application.Certificates;
namespace TechnifyERP.Areas.Admin.Controllers;[Area("Admin"),Authorize(Roles="SuperAdmin")]public sealed class CertificatesController(ICertificateService service):Controller{public async Task<IActionResult>Index(CancellationToken ct){ViewBag.Eligible=(await service.GetEligibleAsync(ct)).Select(x=>new SelectListItem($"{x.RegistrationNumber} — {x.StudentName} · {x.CourseCode}",$"{x.StudentUserId}|{x.CourseId}"));return View(await service.GetAllAsync(ct));}[HttpPost,ValidateAntiForgeryToken]public async Task<IActionResult>Issue(string enrollment,CancellationToken ct){var p=(enrollment??"").Split('|');if(p.Length!=2||!int.TryParse(p[1],out var course))return RedirectToAction(nameof(Index));var r=await service.IssueAsync(User.FindFirstValue(ClaimTypes.NameIdentifier)!,p[0],course,ct);TempData[r.Result==CertificateActionResult.Success?"SuccessMessage":"ErrorMessage"]=r.Result==CertificateActionResult.Success?"Certificate issue ho gaya.":r.Result==CertificateActionResult.Duplicate?"Certificate pehle se issued hai.":"Certificate issue nahi hua.";return RedirectToAction(nameof(Index));}public async Task<IActionResult>Print(int id,CancellationToken ct){var x=await service.GetForUserAsync(User.FindFirstValue(ClaimTypes.NameIdentifier)!,id,true,ct);return x is null?NotFound():View(x);}}
